    display:none;margin-top:8px;padding-top:8px;border-top:1px dashed #cbd5e1;
    font-size:12.3px;line-height:1.6;color:#475569;
  }
  .option-card.correct .opt-feedback,
  .option-card.wrong .opt-feedback{display:block;}

  .axis-tick{font-size:11.5px;fill:#64748b;}
  .axis-label{font-size:12.5px;fill:#475569;font-weight:500;}
  .beaker-title{font-size:13.5px;font-weight:700;fill:#334155;}
  .beaker-status{font-size:11.5px;fill:#64748b;}
  .mini-label{font-size:10.5px;fill:#94a3b8;font-weight:700;}
</style>
</head>
<body>

<header>
  <h1>导电能力为什么先降后升？</h1>
  <p class="subtitle">拖动滑块或播放滴加，观察曲线、烧杯中的离子与沉淀怎样同步变化。</p>
</header>

<main>

  <!-- 题目 -->
  <section class="card prompt">
    <div class="mark">?</div>
    <div class="prompt-body">
      <p>某同学向一定体积的 Ba(OH)₂ 溶液中滴加稀硫酸，测得混合溶液的导电能力随时间变化如图。下列说法正确的是（　　）</p>
    </div>
    <div class="thumb-wrap">
      <svg id="thumb" viewBox="0 0 300 168" role="img" aria-label="题图曲线示意"></svg>
      <span class="thumb-cap">题图曲线（示意）</span>
    </div>
  </section>

  <!-- 主区：曲线 + 烧杯 -->
  <div class="grid-2">

    <section class="card">
      <div class="card-head">
        <h2>导电能力曲线</h2>
        <span class="tag" id="chartTag">原实验</span>
      </div>
      <svg id="chart" viewBox="0 0 620 390" role="img" aria-label="导电能力随滴加量变化曲线"></svg>
      <div class="controls">
        <button id="playBtn">播放滴加</button>
        <input id="tSlider" type="range" min="0" max="8" step="1" value="0" aria-label="滴加量">
        <span id="tLabel" class="num-chip">0 份</span>
        <span id="freeLabel" class="num-chip grey">自由离子：0</span>
      </div>
      <p style="margin:8px 0 0;font-size:11.5px;color:#94a3b8;line-height:1.5;">
        说明：本图的纵坐标是「自由离子数」，用来近似表示导电能力，因此曲线是折线。真实测量得到的导电能力曲线是平滑的，但「先降后升、最低点位置、最低点是否为 0」这几个关键特征完全一致。
      </p>
    </section>

    <section class="card">
      <div class="card-head">
        <h2>烧杯中的粒子</h2>
        <span class="tag" id="expTag">原实验</span>
      </div>
      <svg id="beaker" viewBox="0 0 420 390" role="img" aria-label="烧杯中的离子与沉淀示意"></svg>
      <div id="legend" class="legend"></div>
    </section>

  </div>

  <!-- 探索 -->
  <section class="card explore">
    <div class="card-head">
      <h2>换一种试剂，曲线还一样吗？</h2>
      <span class="tag">点击对比，再拖动滑块</span>
    </div>

    <div class="exp-tabs" id="expTabs"></div>

    <div class="step-row">
      <span class="step-label">分步观察：</span>
      <span id="stepRow" style="display:flex;gap:8px;flex-wrap:wrap;"></span>
    </div>

    <div id="expInfo" class="exp-info"></div>
  </section>

  <!-- 选项 -->
  <section class="card options">
    <h2>判断下列说法</h2>
    <p class="options-sub">点击任一卡片，页面会切换到对应实验与状态，再结合曲线最低点作出判断。</p>
    <div class="option-grid" id="optionGrid"></div>
  </section>

</main>

<script>
/* =====================  数据模型  ===================== */

const experiments = {
  original:{
    id:'original', tab:'原实验', tagText:'原实验',
    name:'Ba(OH)₂ + 稀H₂SO₄',
    color:'#2563eb',
    eqT:4, maxT:8
  },
  B:{
    id:'B', tab:'B：NaOH', tagText:'B：NaOH + H₂SO₄',
    name:'NaOH + 稀H₂SO₄',
    color:'#ea580c',
    eqT:2, maxT:4
  },
  C:{
    id:'C', tab:'C：KHSO₄', tagText:'C：Ba(OH)₂ + KHSO₄',
    name:'Ba(OH)₂ + 稀KHSO₄',
    color:'#9333ea',
    eqT:4, maxT:8
  },
  D:{
    id:'D', tab:'D：MgSO₄', tagText:'D：Ba(OH)₂ + MgSO₄',
    name:'Ba(OH)₂ + 稀MgSO₄',
    color:'#0d9488',
    eqT:4, maxT:8
  }
};

const state = { exp:'original', t:0, playing:false, timer:null };

function clamp(v,a,b){ return Math.max(a, Math.min(b, v)); }

/* 返回某实验、某滴加量下溶液中的粒子情况 */
function getState(expId, t){
  const ions = { Ba:0, OH:0, H:0, SO4:0, Na:0, K:0, Mg:0 };
  const prec = { BaSO4:0, MgOH2:0 };

  if (expId === 'original'){
    const r = clamp(t, 0, 4);
    ions.Ba  = 4 - r;
    ions.OH  = 8 - 2*r;
    prec.BaSO4 = r;
    ions.SO4 = Math.max(0, t - 4);
    ions.H   = Math.max(0, 2*(t - 4));
  }
  else if (expId === 'B'){
    ions.Na  = 4;
    ions.OH  = Math.max(0, 4 - 2*t);
    ions.SO4 = clamp(t, 0, 4);
    ions.H   = Math.max(0, 2*(t - 2));
  }
  else if (expId === 'C'){
    const r = clamp(t, 0, 4);
    ions.Ba  = 4 - r;
    prec.BaSO4 = r;
    ions.K   = clamp(t, 0, 8);
    ions.OH  = Math.max(0, 8 - t);
    ions.SO4 = Math.max(0, t - 4);
  }
  else if (expId === 'D'){
    const r = clamp(t, 0, 4);
    ions.Ba  = 4 - r;
    ions.OH  = 8 - 2*r;
    prec.BaSO4 = r;
    prec.MgOH2 = r;
    ions.Mg  = Math.max(0, t - 4);
    ions.SO4 = Math.max(0, t - 4);
  }

  for (const k in ions) ions[k] = Math.max(0, ions[k]);
  for (const k in prec) prec[k] = Math.max(0, prec[k]);

  const freeCount = Object.keys(ions).reduce((a,k)=>a+ions[k],0);
  return { ions, prec, freeCount };
}

/* 找出某实验曲线最低点 */
function findMin(id){
  const maxT = experiments[id].maxT;
  let bt = 0, bv = Infinity;
  for (let t = 0; t <= maxT + 1e-6; t += 0.05){
    const v = getState(id, t).freeCount;
    if (v < bv - 1e-9){ bv = v; bt = t; }
  }
  return { t: Math.round(bt*10)/10, v: Math.round(bv*100)/100 };
}

/* =====================  文字宽度估计（用于白底标签） ===================== */
function textW(s, fs){
  let w = 0;
  for (const ch of s){
    w += /[\u4e00-\u9fa5]/.test(ch) ? fs : fs*0.62;
  }
  return w;
}
function labelBox(x, y, text, color, fs, anchor){
  fs = fs || 11.5;
  const w = textW(text, fs) + 12;
  const h = fs + 8;
  let bx = x - w/2;
  if (anchor === 'start') bx = x - 6;
  if (anchor === 'end') bx = x - w + 6;
  return `<rect x="${bx.toFixed(1)}" y="${(y-h/2).toFixed(1)}" width="${w.toFixed(1)}" height="${h}" rx="5"
            fill="#ffffff" stroke="${color}" stroke-width="1.1" opacity="0.96"/>` +
         `<text x="${x}" y="${y}" text-anchor="${anchor||'middle'}" dominant-baseline="central"
            font-size="${fs}" font-weight="700" fill="${color}">${text}</text>`;
}

/* =====================  题图缩略（平滑曲线） ===================== */
function drawThumb(){
  const svg = document.getElementById('thumb');
  let s = '';
  s += `<line x1="34" y1="140" x2="282" y2="140" stroke="#475569" stroke-width="2"/>`;
  s += `<line x1="34" y1="140" x2="34" y2="22" stroke="#475569" stroke-width="2"/>`;
  s += `<path d="M34 22 L29 32 L39 32 Z" fill="#475569"/>`;
  s += `<path d="M282 140 L272 135 L272 145 Z" fill="#475569"/>`;
  s += `<text x="288" y="145" font-size="11" fill="#64748b">时间</text>`;
  s += `<text x="12" y="26" font-size="11" fill="#64748b">导电</text>`;
  s += `<text x="12" y="39" font-size="11" fill="#64748b">能力</text>`;
  s += `<text x="22" y="154" font-size="11" fill="#64748b">O</text>`;
  s += `<path d="M40 48 C 86 50, 118 74, 152 138 C 174 111, 204 97, 232 91 C 249 88, 262 86, 276 85"
          fill="none" stroke="#0f172a" stroke-width="2.4" stroke-linecap="round"/>`;
  s += `<text x="58" y="41" font-size="15" font-weight="700" fill="#0f172a" font-family="Georgia,serif">A</text>`;
  s += `<text x="126" y="124" font-size="15" font-weight="700" fill="#0f172a" font-family="Georgia,serif">B</text>`;
